package tr.kasadenge.app;
import android.graphics.*;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.common.InputImage;import com.google.android.gms.tasks.*;import org.json.*;import java.util.*;import java.util.function.Consumer;
/** Additional, device-local reads of the blue handwritten fields on the printed cashbook. */
final class CashbookOcr {
 static List<Text.Element> elements(Text t){List<Text.Element> a=new ArrayList<>();for(Text.TextBlock b:t.getTextBlocks())for(Text.Line l:b.getLines())a.addAll(l.getElements());return a;}
 static Rect anchor(List<Text.Element> es,String value,int minX,int maxX){Rect best=null;for(Text.Element e:es){Rect r=e.getBoundingBox();if(r!=null&&e.getText().equals(value)&&r.left>=minX&&r.left<maxX&&(best==null||r.left<best.left))best=r;}return best;}
 static boolean isTemplate(Text t){String s=t.getText().toLowerCase(new Locale("tr","TR"));return (s.contains("kasadan")||s.contains("nakit"))&&anchor(elements(t),"200",0,Integer.MAX_VALUE)!=null;}
 static void fields(Bitmap image,Text first,TextRecognizer reader,Consumer<JSONObject> done){List<Bitmap> allocated=new ArrayList<>();try{
  List<Text.Element> es=elements(first);Rect a=anchor(es,"200",0,image.getWidth()),right=anchor(es,"10",image.getWidth()/2,image.getWidth());for(Text.Element e:es)if(e.getText().toLowerCase(new Locale("tr","TR")).startsWith("bozuk")&&e.getBoundingBox()!=null&&(right==null||right.left-e.getBoundingBox().left>60))right=e.getBoundingBox();if(a==null||right==null){done.accept(new JSONObject());return;}
  int width=image.getWidth(),height=image.getHeight();int[] pixels=new int[width*height];image.getPixels(pixels,0,width,0,0,width,height);for(int i=0;i<pixels.length;i++){int c=pixels[i],r=Color.red(c),g=Color.green(c),b=Color.blue(c);pixels[i]=b-r>12&&b-g>8&&b>r*1.12&&b>g*1.10&&b>50?Color.BLACK:Color.WHITE;}Bitmap ink=Bitmap.createBitmap(pixels,width,height,Bitmap.Config.ARGB_8888);allocated.add(ink);
  LinkedHashMap<String,Task<Text>> jobs=new LinkedHashMap<>();int gap=right.left-a.left,h=Math.max(14,a.height());
  add(jobs,allocated,reader,image,"date",a.left-60,a.top-6*h,a.left+190,a.top-h);
  add(jobs,allocated,reader,ink,"expectedWhole",right.left-gap*.15,a.top-6*h,right.left+gap*.33,a.top-h);
  add(jobs,allocated,reader,ink,"expectedCents",right.left+gap*.33,a.top-6*h,right.left+gap*.54,a.top-h);
  for(int value:new int[]{200,100,50,20,10,5}){boolean left=value>=20;Rect r=anchor(es,String.valueOf(value),left?Math.max(0,a.left-50):right.left-40,left?a.left+80:image.getWidth());if(r==null)continue;int span=left?gap:width-right.left-50,rh=Math.max(14,r.height());add(jobs,allocated,reader,ink,"count"+value,r.right+5,r.top-rh*1.2,r.left+span*.27,r.bottom+rh*.6);add(jobs,allocated,reader,ink,"amount"+value,r.left+span*.30,r.top-rh*1.2,r.left+span*.96,r.bottom+rh*.25);}
  Rect bozuk=null;for(Text.Element e:es)if(e.getText().toLowerCase(new Locale("tr","TR")).startsWith("bozuk")){bozuk=e.getBoundingBox();break;}if(bozuk!=null){int bh=Math.max(14,bozuk.height());add(jobs,allocated,reader,ink,"other",right.left+gap*.30,bozuk.top-bh*1.2,width-40,bozuk.bottom+bh*.4);}
  Tasks.whenAllComplete(new ArrayList<Task<?>>(jobs.values())).addOnCompleteListener(task->{JSONObject out=new JSONObject();try{out.put("template",true);for(Map.Entry<String,Task<Text>> j:jobs.entrySet())if(j.getValue().isSuccessful())out.put(j.getKey(),j.getValue().getResult().getText());}catch(Exception ignored){}finally{for(Bitmap b:allocated)if(!b.isRecycled())b.recycle();}done.accept(out);});
 }catch(Exception e){for(Bitmap b:allocated)if(!b.isRecycled())b.recycle();done.accept(new JSONObject());}}
 static void add(Map<String,Task<Text>> jobs,List<Bitmap> allocated,TextRecognizer reader,Bitmap src,String name,double x1,double y1,double x2,double y2){int l=Math.max(0,(int)x1),t=Math.max(0,(int)y1),r=Math.min(src.getWidth(),(int)x2),b=Math.min(src.getHeight(),(int)y2);if(r-l<8||b-t<8)return;Bitmap crop=Bitmap.createBitmap(src,l,t,r-l,b-t);Bitmap scaled=Bitmap.createScaledBitmap(crop,Math.min(1600,crop.getWidth()*3),crop.getHeight()*3,true);if(crop!=src&&crop!=scaled)crop.recycle();allocated.add(scaled);jobs.put(name,reader.process(InputImage.fromBitmap(scaled,0)));}
}
